INSERT IGNORE INTO `Silos` (`SiloKey`,`Name`,`ShortName`,`Glyph`,`Intro`,`TopGrades`,`DisplayOrder`) VALUES
 ('mild-steel-structural','Mild Steel & Structural','Mild & structural','beam','IS 2062 bars, plates, angles, channels, beams, pipes and hollow sections from SAIL, Tata Steel, JSW, Vizag Steel and APL Apollo, crane-loaded straight onto your truck.','IS 2062 plates, ISMB, ISMC, ERW pipes',1),
 ('alloy-engineering-steels','Alloy & Engineering Steels','Alloy & engineering','round','EN-series, SAE, DIN and tool steels in ready stock: EN8 to EN353, 42CrMo4, D2, D3, H13, DB6 and HSS, band-saw cut to your lengths with mill test certificates.','EN8, EN19, EN24, EN31, D2',2),
 ('stainless-steel','Stainless Steel','Stainless','tube','Austenitic, martensitic and precipitation-hardening grades in bars, sheets, plates, pipes, hex and angles, from food-grade 304 to marine 316L and 17-4PH.','SS 304, 316L, 410, 17-4PH',3),
 ('non-ferrous-metals','Non-Ferrous Metals','Non-ferrous','hex','Brass, electrolytic copper, gunmetal, phosphor bronze, aluminium bronze and aircraft-grade aluminium for bushes, busbars, valves and precision turned parts.','Brass, copper busbar, LG2, PB1, 6061',4),
 ('cast-iron','Cast Iron','Cast iron','square','Continuous-cast grey and SG iron bars, solid and hollow, dense and free of blow holes, for hydraulic blocks, gears, pulleys and machine beds.','FG 250, FG 300, GGG40',5),
 ('engineering-plastics','Engineering Plastics','Plastics','plastic','Nylon, cast nylon, Delrin, PTFE, UHMWPE, PP, Bakelite and acrylic in rods, sheets and blocks for wear pads, bushes, gaskets and insulation.','Nylon 6, PTFE, Delrin',6),
 ('cutting-workshop-tools','Cutting & Workshop Tools','Tools','tool','The consumables that keep a machine shop running: HSS and cobalt tool bits, bi-metal bandsaw blades, carbide inserts, end mills, taps, dies and chuck accessories.','M42 bandsaw blades, HSS bits',7);
