INSERT IGNORE INTO `Cities` (`Slug`,`Name`,`DistanceKm`,`LeadTime`,`Zones`,`Intro`,`IndustriesJson`,`PopularSlugsJson`,`DisplayOrder`) VALUES
 ('madurai','Madurai',0,'Same day','Kappalur SIDCO, K. Pudur, Uranganpatti, Thoppur','Our godowns sit in Simmakkal, minutes from most Madurai workshops. Pick up over the counter, or we deliver cut pieces the same day.','["Lathe and CNC job shops","Pumps and motors","Textile machinery","Fabrication"]','["en8-steel-round-bars","en24-chrome-moly-steel-bars","ms-plates-sheets","free-cutting-brass-rods"]',1),
 ('tirunelveli','Tirunelveli',155,'1 day','Gangaikondan SIPCOT, Pettai, Palayamkottai','Daily trucks run from Madurai to Tirunelveli and the wind-energy belt beyond it, with crane-loaded plates and sections delivered next morning.','["Wind turbine parts","Pumps and valves","Structural fabrication"]','["ms-plates-sheets","en19-alloy-steel-rounds","ss-304-round-bars","gunmetal-lg2-rods"]',2),
 ('virudhunagar','Virudhunagar',50,'Same day','Virudhunagar SIDCO, Aruppukottai road','An hour down NH 44 from our yard: stainless sheets for oil and food plants and EN8 shafting for mill machinery, delivered the same day.','["Oil mills","Ginning and spinning","Food processing machinery"]','["ss-304-sheets-plates","en8-steel-round-bars","nylon-6-rods","ms-flat-bars"]',3),
 ('sivakasi','Sivakasi',75,'Same day','Sivakasi industrial estate, Thiruthangal','Printing and converting machines need ground rollers, D2 cutting dies and bronze bushes. We stock all three and send them down the same day.','["Printing presses","Match and safety-fireworks machinery","Paper converting"]','["en31-bearing-steel-rounds","hchcr-d2-tool-steel","phosphor-bronze-pb1-rods","delrin-acetal-white-rods"]',4),
 ('kovilpatti','Kovilpatti',100,'1 day','Kovilpatti SIDCO, Ettayapuram road','Steel, brass and Bakelite for the match and spinning units of Kovilpatti, consolidated on our Tuticorin-route truck.','["Match industry","Spinning mills","General engineering"]','["en8-steel-round-bars","ms-equal-angles","brass-round-bars","bakelite-fabric-sheets"]',5),
 ('tuticorin','Tuticorin',150,'1 day','SIPCOT Tuticorin, V.O.C. Port, Meelavittan','Marine-grade 316, 5083 aluminium and heavy ISMB for the port and plant corridor, dispatched daily and crane-unloaded at site on request.','["Port and marine works","Thermal and chemical plants","Salt and seafood processing"]','["ss-316-plates-sheets","aluminium-5083-plates","ms-beams-ismb","aluminium-bronze-ab2-rods"]',6);
